// A card of its own under the offer, with what it costs.
export function OwnAccountDoor({ onAction, disabled }: { onAction: Action; disabled: boolean }) {
  return (
    <button type="button" className="onboarding-door" disabled={disabled}
      onClick={() => onAction('onboarding_open_preferences', { door: 'key' })}>
      <span className="onboarding-door-text">
        <span className="onboarding-door-name">Use your own AI account</span>
        <span className="onboarding-door-what">Your API key, or Claude Code or Claude Desktop</span>
      </span>
      <span className="onboarding-door-cost">Free</span>
    </button>
  );
}

function Welcome({ onboarding, appearance, onAction }: Props) {
  const signingIn = onboarding.signIn !== 'idle';
  // The other doors stay open while the person signs in, as canvas boards
  // first-run-04 and 12 to 16 draw them, and close only while the account is read.
  const checking = onboarding.signIn === 'checking';
  // Only a sign-in finished here moves on by itself. Someone who comes Back
  // already signed in sees who, and goes on with Continue.
  const waited = useRef(false);
  if (signingIn) waited.current = true;
  const signedIn = Boolean(onboarding.accountEmail) && !signingIn;
  useEffect(() => {
    if (!signedIn || !waited.current) return;
    const timer = setTimeout(() => onAction('onboarding_leave_welcome'), SIGNED_IN_PAUSE_MS);
    return () => clearTimeout(timer);
  }, [signedIn, onAction]);

  return (
    <div className="onboarding">
      <Lockup appearance={appearance} className="onboarding-lockup" />
      <div className="onboarding-welcome">
        <figure className="onboarding-clip">
          <video src={clip} autoPlay loop muted playsInline aria-label="AI fixing a print that came out stringy" />
          <details className="onboarding-credits">
            <summary>Photo credits</summary>
            <p>
              “Dual extrusion 3D printed #3DBenchy v01” by #3DBenchy, flickr.com/photos/3dbenchy/19273965123, CC BY 2.0
              (creativecommons.org/licenses/by/2.0). Cropped.
            </p>
            <p>
              “Dual-print multi-part color 3D print of #3DBenchy v13” by #3DBenchy, flickr.com/photos/3dbenchy/19239738473,
              CC BY 2.0 (creativecommons.org/licenses/by/2.0). Cropped and resized.
            </p>
          </details>
        </figure>
        <div className="onboarding-pitch">
          <div className="onboarding-heading">
            <h1>The AI slicer that helps you get better prints.</h1>
            <p className="onboarding-lead">
              Show it a photo of what went wrong. AI reads your file, your settings and your slice, changes the settings
              and slices again.
            </p>
          </div>
          {/* Once signed in there is nothing left to choose: only the credits
              card, with Continue, stays. */}
          <div className="onboarding-doors">
            {!signedIn && <p className="onboarding-doors-label">Sign up to use AI, or skip it and just slice.</p>}
            <div className="onboarding-offer">
              <SignInDoor onboarding={onboarding} onAction={onAction} offer />
              {signedIn && !waited.current && (
                <button type="button" className="button-primary onboarding-door-button"
                  onClick={() => onAction('onboarding_leave_welcome')}>
                  Continue
                </button>
              )}
            </div>
            {!signedIn && (
              <>
                <OwnAccountDoor onAction={onAction} disabled={checking} />
                <button type="button" className="onboarding-link flush" disabled={checking}
                  onClick={() => onAction('onboarding_leave_welcome')}>
                  Just slice for now
                </button>
              </>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

// What the welcome finished, above the first printer screen's headline:
// who signed in, or whose key the agent uses. Nothing after "Just slice for
// now".
function WelcomeDone({ onboarding }: { onboarding: OnboardingState }) {
  const { account, accountEmail } = onboarding;
  if (accountEmail && account) {
    return (
      <div className="onboarding-done">
        <CheckGlyph />
        <span className="onboarding-done-text">
          <span>{signedInCredits(account)}</span>
---- AGENTGROUP
}) {
  if (onboarding.agentCard === 'none') {
    if (!setupHidden) return null;
    return (
      <section className="agent-group" aria-label="AI">
        <p className="agent-setup-hidden">
          AI setup won’t show here again. You can set it up later in{' '}
          <button type="button" className="onboarding-link agent-setup-hidden-link" onClick={onOpenPreferences}>
            Preferences
          </button>, under the gear at the top right.
        </p>
      </section>
    );
  }
  return (
    <section className="agent-group" aria-label="AI">
      {onboarding.agentCard === 'account' ? (
        <Account onboarding={onboarding} onAction={onAction} />
      ) : (
        <div className="agent-card">
          <div className="agent-card-head">
            <strong className="agent-card-heading">Set up AI</strong>
            <button type="button" className="onboarding-link agent-card-hide" onClick={onHideSetup}>
              Don’t show again
            </button>
          </div>
          {onboarding.signIn === 'idle' && !onboarding.accountEmail && (
            <p className="agent-card-why">Get {creditNumber(SIGNUP_CREDITS)} free credits and ask AI to improve your prints.</p>
          )}
          <SignInDoor onboarding={onboarding} onAction={onAction} />
          <OwnAccountDoor onAction={onAction} disabled={onboarding.signIn === 'checking'} />
        </div>
      )}
    </section>
  );
}
---- CREDITS
export const TIER_NAMES: Record<string, string> = { basic: 'Standard', expert: 'Expert' };

// The sign-up offer, wherever someone can make an account. The gateway grants
// a new account 500 credits (JUSPRIN_V2_SIGNUP_CREDITS) for a month from the
// day it is granted. A Standard message costs 1 and an Expert message 5 (the
// gateway's model aliases, checked on staging 2026-11-07). Nothing asks the
// gateway before sign-in.
// No plan is named: someone who has not signed up has none to choose.
export const SIGNUP_CREDITS = 500;
const STANDARD_MESSAGE_CREDITS = 1;
const EXPERT_MESSAGE_CREDITS = 5;
export const SIGNUP_OFFER = `Sign up and get ${creditNumber(SIGNUP_CREDITS)} free credits`;
export const SIGNUP_SCALE =
  `Good for your first month: about ${SIGNUP_CREDITS / STANDARD_MESSAGE_CREDITS} ${TIER_NAMES.basic} ` +
  `or ${SIGNUP_CREDITS / EXPERT_MESSAGE_CREDITS} ${TIER_NAMES.expert} messages.`;
// The price of a message on Account. GET /account carries no prices, so these
// are the same constants as the offer's.
export const MESSAGE_PRICES =
  `Each message you send costs credits: ${TIER_NAMES.basic} ${STANDARD_MESSAGE_CREDITS}, ` +
  `${TIER_NAMES.expert} ${EXPERT_MESSAGE_CREDITS}.`;
// What a free account gets once the first month is over, under the offer
// where it is drawn at rest. 50 a month is the free plan's monthly grant,
// confirmed for the welcome on 2026-11-06; nothing here reads it.
export const SIGNUP_AFTER = 'After that, 50 free credits a month. No card needed.';

// "4 December".
const longDate = (iso: string) => new Date(iso).toLocaleDateString('en-GB', { day: 'numeric', month: 'long' });

// What signing in got the person, the line above who signed in: the free
// credits a new account was just given, or what an account they used before
// has left.
export function signedInCredits(account: CreditAccount, now: Date = new Date()): string {
  const signup = account.credits.lots.find((lot) => lot.kind === 'signup');
  if (signup?.expires_at && signup.credits === signup.granted && new Date(signup.expires_at) > now)
    return `You got ${creditNumber(signup.granted)} free credits for signing up, good until ${longDate(signup.expires_at)}.`;
  return `You have ${creditCount(account.credits.total)}.`;
}

// Why the next message of this chat cannot be paid, or nothing when it can.
export function sendBlock(account: CreditAccount | null | undefined, model: ModelOptionInfo | undefined): string | undefined {
  if (!account || !model?.tier) return undefined;

  const ownKey = !signedIn && savedKeys.length > 0;
  // The server's box is asked for when Account opens, after a sign-in or
  // out, and on coming back from the browser, where a pack may have been
  // bought.
  useEffect(() => {
    if (ownKey)
      return;
    actions.refreshAccountBox();
    const refresh = () => actions.refreshAccountBox();
    window.addEventListener('focus', refresh);
    return () => window.removeEventListener('focus', refresh);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [signedIn, ownKey]);
  return (
    <section className="prefs-section prefs-account" aria-label="Account">
      <h2 className="prefs-title">Account</h2>
      {!ownKey && accountBox && <AccountBox key={accountBox} html={accountBox} />}
      <JusPrinAccount savedKeys={savedKeys} account={account} modelCatalog={modelCatalog} actions={actions} />
      {signedIn && creditAccount && (
        <AccountCredits account={creditAccount} onOpenPage={actions.openServerPage} />
      )}
      <div className="prefs-callout">
        <span className="jp-icon jp-icon-lock" aria-hidden="true" />
        <p>
          With a JusPrin account, JusPrin receives your messages, the open project’s settings and anything you attach,
          and passes them on to the model provider it uses.
        </p>
      </div>
      {signedIn ? (
        <>
          <p className="prefs-note">Signing out keeps your projects, printers and API keys on this computer.</p>
          <DeleteAccount email={savedKeys.find((key) => key.provider === 'jusprin')?.account}
            warning={creditAccount?.delete_warning} accountDeleted={accountDeleted} onDelete={actions.deleteAccount} />
        </>
      ) : (
        <p className="prefs-note">
          Local work never needs an account. Your own API key or AI tool works without one; set those up in the{' '}
          <button type="button" className="link prefs-inline-link" onClick={onAgent}>BYOAI</button> section.
        </p>
      )}
    </section>
  );
}

function AgentSection({ agent, setup, savedKeys, mcpCatalog, actions, onConnectTool, onAccount }: {
  agent: PreferencesPayload['agent']; setup: SetupStatusPayload; savedKeys: SavedKeyInfo[];
  mcpCatalog: McpCatalogPayload | null; actions: PreferencesActions; onConnectTool: (tool: McpToolInfo) => void;
  onAccount: () => void;
}) {
  // The tools are looked for once each time the section opens.
  useEffect(() => {
    actions.refreshTools();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);
  return (
    <section className="prefs-section" aria-label="BYOAI">
      <div className="prefs-head">
        <h2 className="prefs-title">BYOAI</h2>
        <p className="prefs-intro">
          Bring Your Own AI: an API key or an AI app you already pay for. No JusPrin account needed. Set up as many as
          you like; each chat picks a model from them.
        </p>
      </div>
      <ProviderKeys heading setup={setup} savedKeys={savedKeys} onCheck={actions.checkKey} onCancel={actions.cancelCheck}
        onRemove={actions.removeKey} />
      <ToolGroup heading tools={mcpCatalog?.tools ?? []} onConnect={onConnectTool} onLookAgain={actions.refreshTools} />
      <Group title="New chats start with">
        {agent.newChatChoices.length > 0 ? (
          <Row title="Model" detail="A chat keeps the model it started with.">
            <Select label="Model" value={agent.newChatProvider} onChange={(provider) => actions.set('newChatProvider', provider)}
              options={agent.newChatChoices.map((choice) => ({ value: choice.provider,
                // JusPrin's model id is an alias that means nothing to anyone.
                label: choice.provider === 'jusprin' ? choice.label : `${choice.model} · ${choice.label}` }))} />
          </Row>
        ) : (
          <Row title="Model" detail="Add a key above, or sign in under Account, to choose the model new chats start with." />
        )}
      </Group>
      <div className="prefs-callout">
        <span className="jp-icon jp-icon-lock" aria-hidden="true" />
        <p>
