async (page) => {
  const S = '/private/tmp/claude/claude-502/-Users-kenneth--claude-spares-spare-sN2SQi/dfe4dcbb-035f-4143-8606-810d508fc78c/scratchpad/shots/';
  const browser = page.context().browser();
  const out = [];
  const shots = [
    ['menu-1-today', ''],
    ['menu-2-with-line', '?menu=' + encodeURIComponent('Specializes in 3D printing')],
  ];
  for (const [name, query] of shots) {
    const ctx = await browser.newContext({ viewport: { width: 429, height: 752 }, deviceScaleFactor: 2 });
    const p = await ctx.newPage();
    await p.goto('http://127.0.0.1:8791/agent.html' + query);
    const button = p.getByRole('button', { name: /^Model/ });
    await button.waitFor({ timeout: 5000 });
    await button.click();
    await p.waitForTimeout(400);
    const menuText = await p.locator('[role="menu"]').first().innerText().catch((e) => 'no menu: ' + e.message);
    await p.screenshot({ path: S + name + '.png' });
    out.push([name, menuText]);
    await ctx.close();
  }
  return out;
}

