.chat-menu {
  position: absolute;
  top: calc(100% + 16px);
  right: 0;
  z-index: 2;
  display: flex;
  flex-direction: column;
  gap: 4px;
  min-width: 128px;
  padding: var(--popover-padding-y) 0;
  border: var(--popover-border-width) solid var(--border-subtle);
  border-radius: var(--popover-radius);
  background: var(--surface-raised);
  box-shadow: var(--elevation-medium);
}
.chat-menu-list {
  display: flex;
  flex-direction: column;
  gap: var(--popover-row-gap);
  min-height: 0;
  overflow-y: auto;
}
.chat-menu button {
  display: flex;
  flex: 0 0 auto;
  align-items: center;
  justify-content: flex-start;
  gap: 8px;
  height: var(--menu-row-height);
  margin: 0 var(--menu-row-side-inset);
  padding: 0 12px;
  text-align: left;
  border: 0;
  background: transparent;
  border-radius: var(--menu-row-radius);
}
.chat-menu button:disabled { color: var(--action-disabled-text); }
.chat-menu button:hover:enabled,
.chat-menu button:active:enabled,
.chat-menu button:focus-visible,
.chat-menu button.active { border: 0; background: var(--surface-raised-hover); }
/* A menu row has no focus state of its own: the keyboard's row looks like the
   hovered one. The outside ring would stick out past the popover's edge. */
.chat-menu button:focus-visible { outline: none; }
button.danger { color: var(--status-danger); }
.chat-list-pane { display: flex; flex-direction: column; flex: 1; min-height: 0; background: var(--surface-canvas); }
  font: var(--font-body-small);
  color: var(--text-secondary);
}

/* A row's label takes the width; the current choice's tick sits at the end
   (Menu/Row, Current). */
.chat-menu-text {
  display: flex;
  flex: 1;
  flex-direction: column;
  min-width: 0;
}

.chat-menu-detail {
  font: var(--font-label);
  color: var(--text-secondary);
  white-space: normal;
}

.chat-menu-text .chat-menu-label {
  flex: none;
}

.chat-menu-label {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

